#!/usr/bin/env Rscript
stop_now <- function(...) stop(...,call.=FALSE); root<-normalizePath(".",mustWork=TRUE); a<-commandArgs(trailingOnly=TRUE); val<-function(n){z<-grep(paste0("^--",n,"="),a,value=TRUE);if(length(z)!=1L)stop_now("Require --",n,"=");sub(paste0("^--",n,"="),"",z)}
if(!"--goal-authorized=lane-b-144-goal"%in%a)stop_now("Execution requires active Lane-B goal authority.")
cell<-val("cell");seed<-as.integer(val("seed"));rung<-val("rung");out<-val("output-dir"); contracts<-utils::read.delim(file.path(root,"docs/dev-log/interval-campaign-bindings/2026-07-30-q4-provider-highinfo-canonical-contracts.tsv"),check.names=FALSE,stringsAsFactors=FALSE); row<-contracts[contracts$cell_id==cell,,drop=FALSE];if(nrow(row)!=1L||seed!=row$seed[[1L]]||!identical(rung,row$execution_information_rung[[1L]]))stop_now("Arguments differ from exact q4 provider contract.")
sha<-system2("git",c("-C",root,"rev-parse","HEAD"),stdout=TRUE)[[1L]]; expected<-file.path(root,"docs/dev-log/interval-feasibility/results",sha,"q4-provider-highinfo",cell); actual<-normalizePath(if(grepl("^/",out))out else file.path(root,out),mustWork=FALSE);if(!identical(actual,expected))stop_now("Output must use source-SHA path: ",expected);dir.create(actual,recursive=TRUE,showWarnings=FALSE); paths<-setNames(file.path(actual,c("trace.tsv","interval.tsv","receipt.tsv")),c("trace","interval","receipt"));if(any(file.exists(paths)))stop_now("Refusing to replace retained artifacts.")
write_tsv<-function(x,p)utils::write.table(x,p,sep="\t",quote=FALSE,row.names=FALSE,na="");hash<-function(p){cmd<-if(nzchar(Sys.which("sha256sum")))"sha256sum"else"shasum";z<-system2(cmd,if(cmd=="sha256sum")p else c("-a","256",p),stdout=TRUE);sub("\\s.*$","",z[[1L]])};stage<-"source_load"
tryCatch({pkgload::load_all(root,quiet=TRUE,export_all=FALSE);e<-new.env(parent=globalenv());sys.source(file.path(root,"tools/lane-b-q4-provider-highinfo-adapters.R"),e);stage<-"fixture";fxt<-e$lane_b_q4_provider_fixture(cell,seed,rung);stage<-"fit";fit<-fxt$fit();target<-row$profile_parameter[[1L]];t<-drmTMB::profile_targets(fit);if(nrow(t[t$parm==target&t$profile_ready,,drop=FALSE])!=1L)stop_now("Target not uniquely profile-ready.");stage<-"profile";pr<-stats::profile(fit,parm=target,trace=TRUE);tr<-as.data.frame(pr);status<-unique(as.character(tr$conf.status));msg<-unique(as.character(tr$profile.message));lo<-unique(as.numeric(tr$conf.low));hi<-unique(as.numeric(tr$conf.high));est<-unique(as.numeric(tr$estimate));d<-drmTMB:::profile_interval_diagnostics(c(lo,hi),transformation=unique(tr$transformation)[[1L]],estimate=est);cors<-unname(fit$corpars[[row$provider[[1L]]]]);cbd<-length(cors)>0&&any(abs(cors)>=.995);complete<-nrow(tr)>0&&length(status)==1L&&length(msg)==1L&&identical(status,"profile")&&identical(msg,"ok");pass<-complete&&!isTRUE(d$boundary)&&!cbd&&is.finite(est)&&is.finite(lo)&&is.finite(hi)&&lo<hi&&est>=lo&&est<=hi&&fit$opt$convergence==0L&&isTRUE(fit$sdr$pdHess);tr$cell_id<-cell;tr$target_id<-row$target_id;write_tsv(tr,paths[["trace"]]);write_tsv(data.frame(cell_id=cell,target_id=row$target_id,estimate=est,lower=lo,upper=hi,profile_engine="tmbprofile"),paths[["interval"]]);write_tsv(data.frame(cell_id=cell,target_id=row$target_id,dgp_id=row$dgp_id,provider=row$provider,seed=seed,information_rung=rung,source_sha=sha,profile_engine="tmbprofile",conf_status=if(pass)"profile"else"profile_failed",estimate=est,lower=if(pass)lo else NA_real_,upper=if(pass)hi else NA_real_,convergence=fit$opt$convergence,pdHess=isTRUE(fit$sdr$pdHess),profile_boundary=isTRUE(d$boundary),correlation_boundary=cbd,clamp_limited=identical(status,"clamp_limited"),trace_complete=complete,failure_reason=if(pass)NA_character_ else msg,trace_sha256=hash(paths[["trace"]]),interval_sha256=hash(paths[["interval"]])),paths[["receipt"]])},error=function(err){write_tsv(data.frame(cell_id=cell,target_id=row$target_id,dgp_id=row$dgp_id,source_sha=sha,conf_status="profile_failed",trace_complete=FALSE,failure_reason=paste0(stage,": ",conditionMessage(err))),paths[["receipt"]]);stop(err)})
